function CLASSIFY_RAY(sizes[0..n-1]):
    antitone <- true; monotone <- true
    for i in 0..n-2:
        if sizes[i+1] > sizes[i]: antitone <- false
        if sizes[i+1] < sizes[i]: monotone <- false
    if antitone:
        return ("finite", MIN(sizes))
    if monotone:
        if sizes[n-1] > sizes[0]: return ("infinite", none)
        return ("finite", MIN(sizes))
    return ("oscillating", none)   // only possible when monotonicity fails

function STABILIZATION_INDEX(sizes[0..n-1]):
    d <- MIN(sizes)
    for N0 in 0..n-1:
        if for all m in N0..n-1: sizes[m] = d:
            return N0
    return none

